package org.circus.core;
import java.io.*;
public final class Pc1WindowMemoryTests {
 private static int checks;private static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 private static Pc1NativeMemory bus(){return new Pc1NativeMemory(Pc1NativeFrame.zeroBss(),Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){public int read(int at){return 0;}public void write(int at,int value){}});}
 public static int run()throws Exception{checks=0;Pc1NativeMemory bus=bus();Pc1WindowMemory owner=new Pc1WindowMemory(bus);check(owner.nativeMemory()==bus,"same canonical bus");for(int n=0;n<40;n++)check(bus.readAddress(0x94c2e0+n)==0,"loaded BSS header zero");for(int n=0;n<40;n++)bus.writeAddress(0x94c2e0+n,n*31+3);ByteArrayOutputStream out=new ByteArrayOutputStream();owner.save(new DataOutputStream(out));check(out.size()==48,"P1WM exact40B once plus magic/version");for(int n=0;n<40;n++)bus.writeAddress(0x94c2e0+n,0);owner.restore(Pc1WindowMemory.loadImage(new DataInputStream(new ByteArrayInputStream(out.toByteArray()))));for(int n=0;n<40;n++)check(bus.readAddress(0x94c2e0+n)==((n*31+3)&255),"all bytes restore in place");boolean reject=false;try{new Pc1WindowMemory(bus);}catch(IOException expected){reject=true;}check(reject,"duplicate owner rejected");for(int address:new int[]{0x94c2df,0x94c308}){reject=false;try{bus.readAddress(address);}catch(IOException expected){reject=true;}check(reject,"exact exclusive header boundary");}byte[] wrong=out.toByteArray();wrong[0]^=1;reject=false;try{Pc1WindowMemory.loadImage(new DataInputStream(new ByteArrayInputStream(wrong)));}catch(IOException expected){reject=true;}check(reject,"unknown magic rejected");wrong=out.toByteArray();wrong[7]=2;reject=false;try{Pc1WindowMemory.loadImage(new DataInputStream(new ByteArrayInputStream(wrong)));}catch(IOException expected){reject=true;}check(reject,"unknown version rejected");return checks;}
 public static void main(String[] args)throws Exception{System.out.println("Pc1WindowMemoryTests PASS "+run()+" assertions");}
}
